from flask import Flask,request,render_template_string
app=Flask(__name__)
PAGE="""<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'><title>SmartCV</title><style>*{box-sizing:border-box}body{font:16px/1.6 Inter,system-ui;background:linear-gradient(135deg,#eaf0ff,#f6f8fc);padding:24px;color:#192942}.box{max-width:900px;margin:18px auto;background:white;padding:clamp(20px,4vw,38px);border:1px solid #e0e7f1;border-radius:22px;box-shadow:0 18px 55px #1e31541a}h1{letter-spacing:-.04em}input,textarea{width:100%;padding:12px;margin:7px 0 15px;border:1px solid #ccd6e5;border-radius:10px;font:inherit}button{padding:12px 17px;background:#345ee8;color:white;border:0;border-radius:10px;font-weight:700;cursor:pointer}.resume{border-top:2px solid #345ee8;margin-top:28px;padding-top:20px}.hint{color:#71809a}@media print{body{background:white;padding:0}.box{box-shadow:none;border:0}form,button,.hint{display:none}}</style><div class=box><h1>SmartCV — Resume Builder</h1><p class=hint>Enter details, preview, then Print → Save as PDF.</p><form method=post>{% for key,label in fields %}<label>{{label}}{% if key in ['summary','experience'] %}<textarea name={{key}} rows=4>{{data[key]}}</textarea>{% else %}<input name={{key}} value="{{data[key]}}" {% if key=='name' %}required{% endif %}>{% endif %}</label>{% endfor %}<button>Update preview</button></form><section class=resume><h1>{{data.name or 'Your Name'}}</h1><h3>{{data.headline}}</h3><p>{{data.email}}</p><h2>Profile</h2><p>{{data.summary}}</p><h2>Skills</h2><p>{{data.skills}}</p><h2>Education & Experience</h2><p style='white-space:pre-line'>{{data.experience}}</p><button onclick=print()>Save as PDF</button></section></div>"""
FIELDS=[('name','Full name'),('headline','Professional headline'),('email','Email'),('summary','Summary'),('skills','Skills (comma separated)'),('experience','Education / experience')]
@app.route('/',methods=['GET','POST'])
def home():
 d={k:'' for k,_ in FIELDS}
 if request.method=='POST':d.update({k:request.form.get(k,'').strip() for k,_ in FIELDS})
 return render_template_string(PAGE,data=d,fields=FIELDS)
if __name__=='__main__':app.run(debug=False)
